<?php $e = static fn (mixed $value): string => App\Core\View::e($value); ?>
<section class="news-admin-preview">
    <div class="section-heading"><div><p class="eyebrow">Prévia administrativa</p><h1><?= $e($article['title']) ?></h1><p><?= $e($article['championship_name']) ?> | <?= $e($article['status']) ?> | autor: <?= $e($article['author_name']) ?></p></div><div><a class="button" href="<?= $e(App\Core\Config::url('/admin/noticias/' . $article['id'] . '/editar')) ?>">Editar</a></div></div>
    <?php if (!empty($message)): ?><p class="success"><?= $e($message) ?></p><?php endif; ?>
    <?php if (!empty($article['cover_image_path'])): ?><img class="news-cover" src="<?= $e(App\Core\Config::url('/admin/noticias/' . $article['id'] . '/capa')) ?>" alt="Capa da noticia"><?php endif; ?>
    <p class="news-summary"><?= $e($article['summary']) ?></p><div class="news-content"><?= nl2br($e($article['content'])) ?></div>
    <div class="inline-actions"><?php if ($article['status'] !== 'published'): ?><form method="post" action="<?= $e(App\Core\Config::url('/admin/noticias/' . $article['id'] . '/publicar')) ?>"><input type="hidden" name="_csrf" value="<?= $e(App\Core\Security::csrfToken()) ?>"><button type="submit">Publicar agora</button></form><?php else: ?><form method="post" action="<?= $e(App\Core\Config::url('/admin/noticias/' . $article['id'] . '/despublicar')) ?>"><input type="hidden" name="_csrf" value="<?= $e(App\Core\Security::csrfToken()) ?>"><button type="submit">Despublicar</button></form><?php endif; ?><form method="post" action="<?= $e(App\Core\Config::url('/admin/noticias/' . $article['id'] . '/excluir')) ?>"><input type="hidden" name="_csrf" value="<?= $e(App\Core\Security::csrfToken()) ?>"><button type="submit">Arquivar</button></form></div>
</section>
